 [STAThread] static int Main(string[] args){
  Args=args;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);System.Net.ServicePointManager.SecurityProtocol=(System.Net.SecurityProtocolType)3072;
  try{
   Root=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"Anomalia IPTV Data");
   int at=Array.IndexOf(args,"--data");if(at>=0&&at+1<args.Length)Root=Path.GetFullPath(args[at+1]);
   Directory.CreateDirectory(Root);string probe=Path.Combine(Root,".write-test");File.WriteAllText(probe,"");File.Delete(probe);
   if(!File.Exists(Path.Combine(Root,"runtime-vlc-3.0.24","complete.txt"))){using(var splash=new Form{Text="Anomalia IPTV",Size=new Size(470,130),StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,ControlBox=false,BackColor=Color.FromArgb(23,29,42),ForeColor=Color.White}){splash.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Подготвям видео двигателя…\r\nТова е необходимо само при първото пускане.",TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",11)});splash.Show();Application.DoEvents();Runtime.Prepare(Root);}}else Runtime.Prepare(Root);
   Application.Run(new MainWindow());return 0;
  }catch(Exception e){MessageBox.Show("Anomalia IPTV не може да стартира.\r\n\r\n"+e.Message+"\r\n\r\nПоставете EXE файла в собствена папка с право за запис. Нужни са 64-битов Windows и .NET Framework 4.8.","Anomalia IPTV",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}
 }
 public static string Arg(string key){int i=Array.IndexOf(Args,key);return i>=0&&i+1<Args.Length?Args[i+1]:"";}
