 void Status(string text){status.Text=text;}
 void Error(Exception e){Status("Действието не завърши.");MessageBox.Show(this,e.Message,"Anomalia IPTV",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 async Task Run(Func<Task> task){if(busy)return;busy=true;profiles.Enabled=false;UseWaitCursor=true;try{await task();}catch(Exception e){Error(e);}finally{busy=false;profiles.Enabled=true;UseWaitCursor=false;}}
 void Save(){store.Write("settings.json",settings);}
 void RefreshProfiles(){profiles.Items.Clear();foreach(var p in settings.Profiles)profiles.Items.Add(p);current=settings.Profiles.FirstOrDefault(p=>p.Id==settings.LastProfile)??settings.Profiles.FirstOrDefault();if(current!=null)profiles.SelectedItem=current;else{channels.Clear();RefreshGroups();}}
 void AddProfile(){using(var d=new ProfileDialog(new Profile(),App.Root)){if(d.ShowDialog(this)==DialogResult.OK){settings.Profiles.Add(d.Value);settings.LastProfile=d.Value.Id;Save();RefreshProfiles();Run(RefreshRemote).ConfigureAwait(false);}}}
 void EditProfile(){if(current==null){AddProfile();return;}using(var d=new ProfileDialog(current,App.Root)){if(d.ShowDialog(this)==DialogResult.OK){int i=settings.Profiles.IndexOf(current);if(d.Deleted){settings.Profiles.RemoveAt(i);channels.Clear();current=null;}else settings.Profiles[i]=d.Value;Save();RefreshProfiles();}}}
 async Task RefreshRemote(){if(current==null){AddProfile();return;}Status("Зареждане от доставчика…");var p=current;var loaded=await provider.Load(p);if(IsDisposed)return;channels=loaded;store.Write("channels-"+p.Id+".json",channels);Save();back.Visible=false;RefreshGroups();Status(channels.Count+" канала • Двоен клик за възпроизвеждане.");}
 void RefreshGroups(){string selected=groups.SelectedItem as string;groups.Items.Clear();groups.Items.Add("Всички групи");foreach(var g in channels.Select(c=>c.Group).Where(g=>g!="").Distinct().OrderBy(g=>g))groups.Items.Add(g);groups.SelectedItem=selected!=null&&groups.Items.Contains(selected)?selected:"Всички групи";Filter();}
 void Filter(){if(list==null)return;string q=search.Text.Trim();string g=groups.SelectedItem as string;visible=channels.Where(c=>(!onlyFavorites||settings.Favorites.Contains(c.Key))&&(g==null||g=="Всички групи"||c.Group==g)&&(q==""||c.Name.IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0||c.Group.IndexOf(q,StringComparison.CurrentCultureIgnoreCase)>=0)).ToList();list.BeginUpdate();list.Items.Clear();list.Items.AddRange(visible.ToArray());list.EndUpdate();count.Text=visible.Count+" / "+channels.Count+" канала";}
 void DrawChannel(object sender,DrawItemEventArgs e){if(e.Index<0||e.Index>=list.Items.Count)return;var c=(Channel)list.Items[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Color.FromArgb(43,67,73):list.BackColor))e.Graphics.FillRectangle(b,e.Bounds);string star=settings.Favorites.Contains(c.Key)?"★ ":"";TextRenderer.DrawText(e.Graphics,star+c.Name,new Font(Font,FontStyle.Bold),new Rectangle(e.Bounds.X+8,e.Bounds.Y+5,e.Bounds.Width-16,23),list.ForeColor,TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);TextRenderer.DrawText(e.Graphics,(c.Group==""?"Без група":c.Group)+(c.Kind=="series"?"  /  Сериал":""),new Font("Segoe UI",8),new Rectangle(e.Bounds.X+8,e.Bounds.Y+29,e.Bounds.Width-16,17),muted,TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);}
 void ToggleFavorite(Channel c){if(c==null)return;if(settings.Favorites.Contains(c.Key))settings.Favorites.Remove(c.Key);else settings.Favorites.Add(c.Key);Save();Filter();}
 void LayoutScreens(){screens.SuspendLayout();screens.Controls.Clear();screens.ColumnStyles.Clear();screens.RowStyles.Clear();screens.ColumnCount=multi?2:1;screens.RowCount=multi?2:1;for(int i=0;i<(multi?2:1);i++){screens.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,multi?50:100));screens.RowStyles.Add(new RowStyle(SizeType.Percent,multi?50:100));}for(int i=0;i<(multi?4:1);i++)screens.Controls.Add(panes[i],multi?i%2:0,multi?i/2:0);screens.ResumeLayout();}
 void ToggleMulti(){multi=!multi;if(!multi){for(int i=1;i<4;i++)if(players[i]!=null)players[i].Stop();active=0;}LayoutScreens();ApplyVolumes();Status(multi?"Натисни заглавието на екран и избери канал. Чува се избраният екран.":"Един екран.");}
 void SelectPane(int index){active=index;foreach(var p in panes)p.Invalidate();if(playing[active]!=null)channelTitle.Text=playing[active].Name;ApplyVolumes();UpdateGuide();}
 void ApplyVolumes(){for(int i=0;i<4;i++)if(players[i]!=null)players[i].Volume=i==active?settings.Volume:0;}
 async Task Play(Channel c){
  if(c.Kind=="series"){Status("Зареждане на епизоди…");channels=await provider.Episodes(current,c);RefreshGroups();back.Visible=true;Status(channels.Count+" епизода • „← Списък“ връща сериалите.");return;}
  Status("Свързване: "+c.Name+"…");int slot=active;string url=await provider.Resolve(current,c);if(IsDisposed)return;
  if(players[slot]==null)players[slot]=new Video(surfaces[slot].Handle);players[slot].Play(url,c,settings);playing[slot]=c;paneLabels[slot].Text=(slot+1)+"  /  "+c.Name;channelTitle.Text=c.Name;settings.LastChannel=c.Key;Save();ApplyVolumes();opened=DateTime.UtcNow;reportedFailure=false;UpdateGuide();if(fullscreen)ShowOverlay();
 }
 void TickPlayer(){var p=players[active];if(p==null)return;try{long duration=p.Length,pos=Math.Max(0,p.Time);seek.Enabled=duration>0;if(duration>0){if(!dragging)seek.Value=(int)Math.Min(1000,1000.0*pos/duration);time.Text=Clock(pos)+" / "+Clock(duration);}else time.Text="НА ЖИВО";
  if(p.Playing)Status((playing[active]==null?"Възпроизвеждане":playing[active].Name)+"  •  "+(multi?"Екран "+(active+1)+"  •  ":"")+"Звук "+settings.Volume+"%  •  F11 цял екран");
  if(p.State==7&&!reportedFailure){reportedFailure=true;Status("Потокът не се отвори. Проверете профила, абонамента и адреса на канала.");}UpdateGuide();
 }catch(ObjectDisposedException){}}
 static string Clock(long ms){var t=TimeSpan.FromMilliseconds(ms);return t.TotalHours>=1?t.ToString(@"h\:mm\:ss"):t.ToString(@"mm\:ss");}
 async Task LoadEpg(){if(current==null||String.IsNullOrWhiteSpace(current.Epg)){Status("Въведете EPG адрес в „Профил“.");EditProfile();return;}Status("Зареждане на телевизионната програма…");byte[] data=File.Exists(current.Epg)?File.ReadAllBytes(current.Epg):await Net.Bytes(current.Epg,settings.UserAgent,null,80*1024*1024);epg=await Task.Run(()=>EpgFormats.Parse(data));File.WriteAllBytes(Path.Combine(App.Root,"epg-cache.bin"),data);UpdateGuide();Status("EPG заредено за "+epg.Items.Count+" канала.");}
 void UpdateGuide(){var c=playing[active];if(c==null)return;var p=epg.Now(c.TvgId,DateTimeOffset.Now);var n=epg.Next(c.TvgId,DateTimeOffset.Now);now.Text=p==null?"СЕГА  /  "+c.Name:p.Start.ToLocalTime().ToString("HH:mm")+" – "+p.Stop.ToLocalTime().ToString("HH:mm")+"  /  "+p.Title;next.Text=p==null?"Няма заредена програма за този канал. Използвай „EPG“. Изисква се съвпадащ tvg-id.":(n==null?"": "СЛЕДВА  "+n.Start.ToLocalTime().ToString("HH:mm")+"  "+n.Title+"\r\n")+p.Description;}
 void ToggleFullscreen(){if(!fullscreen){restore=Bounds;restoreState=WindowState;restoreBorder=FormBorderStyle;WindowState=FormWindowState.Normal;FormBorderStyle=FormBorderStyle.None;Bounds=Screen.FromControl(this).Bounds;sidebar.Visible=false;header.Visible=false;guide.Visible=false;status.Visible=false;workspace.Padding=Padding.Empty;fullscreen=true;lastCursor=Cursor.Position;ShowOverlay();}else{playBar.Visible=true;titleBar.Visible=true;SetPaneChrome(true);FormBorderStyle=restoreBorder;Bounds=restore;WindowState=restoreState;sidebar.Visible=true;header.Visible=true;guide.Visible=true;status.Visible=true;workspace.Padding=new Padding(16,12,16,12);fullscreen=false;}}
 void ShowOverlay(){overlayUntil=DateTime.UtcNow.AddSeconds(5);if(!playBar.Visible){playBar.Visible=true;titleBar.Visible=true;SetPaneChrome(true);}}
 void SetPaneChrome(bool show){screens.SuspendLayout();for(int i=0;i<4;i++){paneLabels[i].Visible=show;panes[i].Padding=show?new Padding(2):Padding.Empty;panes[i].Margin=show||multi?new Padding(2):Padding.Empty;}screens.ResumeLayout();}
 void TracksMenu(){var p=players[active];if(p==null)return;var m=new ContextMenuStrip();foreach(bool audio in new[]{true,false}){var item=new ToolStripMenuItem(audio?"Аудио писта":"Субтитри");foreach(var t in p.Tracks(audio)){bool a=audio;int id=t.Id;item.DropDownItems.Add(t.Name,null,delegate{p.SelectTrack(a,id);});}if(item.DropDownItems.Count==0)item.DropDownItems.Add("Няма налични писти").Enabled=false;m.Items.Add(item);}m.Items.Add("Добави SRT / ASS субтитри…",null,delegate{using(var d=new OpenFileDialog{Filter="Субтитри|*.srt;*.ass;*.ssa;*.vtt|Всички|*.*"})if(d.ShowDialog(this)==DialogResult.OK)p.Subtitle(d.FileName);});m.Items.Add("Снимка на кадъра",null,delegate{try{string folder=Path.Combine(App.Root,"Snapshots");Directory.CreateDirectory(folder);string path=Path.Combine(folder,DateTime.Now.ToString("yyyyMMdd-HHmmss")+".png");p.Snapshot(path);Status("Кадърът е записан в Anomalia IPTV Data / Snapshots.");}catch(Exception e){Error(e);}});m.Items.Add("Копирай адрес на потока",null,async delegate{var c=playing[active];if(c!=null)await Run(async delegate{Clipboard.SetText(await provider.Resolve(current,c));Status("Адресът е копиран.");});});m.Show(Cursor.Position);}
 void OpenSettings(){using(var d=new SettingsDialog(settings)){if(d.ShowDialog(this)==DialogResult.OK){settings.BufferMs=d.Buffer;settings.Hardware=d.Hardware;settings.AutoPlay=d.AutoPlay;settings.Aspect=d.Aspect;settings.Theme=d.Theme;settings.UserAgent=d.Agent;Save();ApplyTheme();foreach(var p in players)if(p!=null)p.Aspect(settings.Aspect);Status("Настройките са записани. Буферът и декодирането се прилагат при следващ канал.");}}}
 void ApplyTheme(){bool light=settings.Theme=="LIGHT";if(settings.Theme=="SYSTEM"){try{light=(int)Registry.GetValue(@"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize","AppsUseLightTheme",0)==1;}catch{}}
  bg=light?Color.FromArgb(235,240,245):Color.FromArgb(14,18,28);surface=light?Color.FromArgb(249,251,253):Color.FromArgb(23,29,42);muted=light?Color.FromArgb(70,85,105):Color.FromArgb(155,170,191);ForeColor=light?Color.FromArgb(20,30,45):Color.White;BackColor=bg;
  PaintTheme(this,light);workspace.BackColor=bg;foreach(var p in panes)p.BackColor=Color.Black;foreach(var p in surfaces)p.BackColor=Color.Black;foreach(var label in paneLabels){label.BackColor=Color.FromArgb(28,34,46);label.ForeColor=Color.White;}now.ForeColor=light?Color.FromArgb(0,110,90):accent;status.ForeColor=muted;count.ForeColor=muted;next.ForeColor=muted;list.Invalidate();
 }
 void PaintTheme(Control root,bool light){foreach(Control c in root.Controls){c.BackColor=surface;c.ForeColor=light?Color.FromArgb(25,35,50):Color.White;if(c is TextBox||c is ComboBox){c.BackColor=light?Color.White:Color.FromArgb(36,44,60);}PaintTheme(c,light);}}
 void BackupMenu(){var m=new ContextMenuStrip();m.Items.Add("Запази пълен архив JSON…",null,delegate{using(var d=new SaveFileDialog{Filter="JSON архив|*.json",FileName="Anomalia-IPTV-backup-"+DateTime.Now.ToString("yyyyMMdd")+".json"})if(d.ShowDialog(this)==DialogResult.OK){var caches=new Dictionary<string,List<Channel>>();foreach(var p in settings.Profiles)caches[p.Id]=store.Cached(p);File.WriteAllText(d.FileName,Storage.Json().Serialize(new Backup{settings=settings,caches=caches}),Encoding.UTF8);Status("Архивът е записан.");}});
  m.Items.Add("Импортирай архив JSON…",null,delegate{ImportBackup();});m.Items.Add("Изнеси видимите канали като M3U…",null,delegate{using(var d=new SaveFileDialog{Filter="M3U списък|*.m3u",FileName="channels.m3u"})if(d.ShowDialog(this)==DialogResult.OK)File.WriteAllText(d.FileName,Playlist.Export(visible),new UTF8Encoding(true));});m.Show(Cursor.Position);}
 void ImportBackup(){using(var d=new OpenFileDialog{Filter="JSON архив|*.json"}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{
  string text=File.ReadAllText(d.FileName,Encoding.UTF8);object obj=Storage.Json().DeserializeObject(text);string app=Provider.S(obj,"app");if(app=="Anomalia IPTV Windows"){
   var b=Storage.Json().Deserialize<Backup>(text);if(b.settings==null||b.caches==null)throw new InvalidDataException("Непълен архив.");foreach(var p in b.settings.Profiles){string old=p.Id;p.Id=Guid.NewGuid().ToString("N");settings.Profiles.Add(p);if(b.caches.ContainsKey(old)){var cached=b.caches[old];store.Write("channels-"+p.Id+".json",cached);if(p.Type=="file"){p.Address=AndroidBackup.SavePlaylist(store,p,cached);}}}foreach(var f in b.settings.Favorites)if(!settings.Favorites.Contains(f))settings.Favorites.Add(f);settings.BufferMs=b.settings.BufferMs;settings.Hardware=b.settings.Hardware;settings.Aspect=b.settings.Aspect;settings.Theme=b.settings.Theme;settings.AutoPlay=b.settings.AutoPlay;settings.UserAgent=b.settings.UserAgent;Save();RefreshProfiles();ApplyTheme();Status("Архивът е добавен като нови профили. Настройките са възстановени.");
  }else{
   int imported=AndroidBackup.Import(obj,settings,store);Save();RefreshProfiles();Status("Възстановени "+imported+" канала и профили от Android архив. EPG адресите се задават от „Профил“.");}
 }catch(Exception e){Error(e);}}}
 void Help(){MessageBox.Show(this,"1. Натисни ＋ и добави M3U URL/файл/текст, Xtream или MAC портал.\r\n2. Обнови списъка и пусни канал с двоен клик / Enter.\r\n3. Десен бутон върху канал: любими и копиране на адрес.\r\n4. „4 екрана“: избери заглавието на екран, после канал.\r\n5. F11 / Esc: цял екран. Space: пауза. Ctrl+F: търсене.\r\n6. „Аудио / CC“: писти, субтитри и снимка.\r\n7. „Архив“ запазва профилите и каналите.\r\n\r\nВсичко се пази до EXE файла в Anomalia IPTV Data.\r\nПремествай EXE и тази папка заедно.\r\nНужен е твой активен IPTV абонамент. Няма включени канали.\r\n\r\nWindows реализация 1.0 • libVLC 3.0.24\r\nПроучване на Android APK: REA + статични Android инструменти.\r\nПодробности и лиценз: README-bg.txt до EXE.","Anomalia IPTV Player",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 async Task VideoTest(string path,string result){var record=new Dictionary<string,object>();try{await Play(new Channel{Name="Локална тестова медия",Url=path.StartsWith("http",StringComparison.OrdinalIgnoreCase)?path:new Uri(Path.GetFullPath(path)).AbsoluteUri});await Task.Delay(6500);var p=players[0];record["playing"]=p.Playing;record["hasVideo"]=p.HasVideo;record["timeMs"]=p.Time;record["durationMs"]=p.Length;record["audioTracks"]=p.Tracks(true).Count;record["subtitleTracks"]=p.Tracks(false).Count;string snapshot=Path.Combine(Path.GetDirectoryName(result),"video-frame.png");p.Snapshot(snapshot);await Task.Delay(500);record["snapshot"]=File.Exists(snapshot);p.Pause();await Task.Delay(250);record["pause"]=!p.Playing;p.Pause();long target=Math.Min(9000,p.Length/2);p.Time=target;await Task.Delay(700);record["seek"]=p.Length<=0||p.Time>=target-1000;using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(Path.GetDirectoryName(result),"app-window.png"));}bool extra=App.Args.Contains("--suite")?await AdditionalTests(record,path,result):true;record["pass"]=extra&&(bool)record["hasVideo"]&&(bool)record["playing"]&&(bool)record["pause"]&&(bool)record["seek"]&&(bool)record["snapshot"];}catch(Exception e){record["error"]=e.ToString();record["pass"]=false;}File.WriteAllText(result,Storage.Json().Serialize(record),Encoding.UTF8);Close();}
}
public class Backup { public string app="Anomalia IPTV Windows",version="1.0",timestamp=DateTimeOffset.UtcNow.ToString("o");public Settings settings;public Dictionary<string,List<Channel>> caches; }

public class ProfileDialog : Form {
 public Profile Value;public bool Deleted=false;TextBox name,address,user,password,mac,epg,paste;ComboBox type,category;string root;
 public ProfileDialog(Profile source,string dataRoot){root=dataRoot;Value=Storage.Json().Deserialize<Profile>(Storage.Json().Serialize(source));Text="Профил на доставчик";Size=new Size(650,730);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(23,29,42);ForeColor=Color.White;
  var form=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(18),AutoScroll=true};form.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));form.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(form);
  name=T(source.Name);type=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};type.Items.AddRange(new object[]{"M3U адрес","M3U файл","M3U текст","Xtream Codes","MAC / Stalker портал"});type.SelectedIndex=source.Type=="file"?1:source.Type=="text"?2:source.Type=="xtream"?3:source.Type=="portal"?4:0;
  address=T(source.Type=="file"&&!Path.IsPathRooted(source.Address)?Path.Combine(root,source.Address):source.Address);user=T(source.Username);password=T(source.Password);password.UseSystemPasswordChar=true;mac=T(source.Mac);epg=T(source.Epg);paste=T("");paste.Multiline=true;paste.ScrollBars=ScrollBars.Vertical;paste.Height=115;
  category=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};category.Items.AddRange(new object[]{"Телевизия на живо","Филми / VOD","Сериали"});category.SelectedIndex=source.Category=="vod"?1:source.Category=="series"?2:0;
  Row(form,"Име",name);Row(form,"Вид",type);Row(form,"Адрес / файл",address);var browse=new Button{Text="Избери M3U файл…",AutoSize=true};browse.Click+=delegate{using(var d=new OpenFileDialog{Filter="M3U|*.m3u;*.m3u8|Всички|*.*"})if(d.ShowDialog(this)==DialogResult.OK){type.SelectedIndex=1;address.Text=d.FileName;}};Row(form,"",browse);
  Row(form,"Потребител",user);Row(form,"Парола",password);Row(form,"MAC адрес",mac);Row(form,"Xtream раздел",category);Row(form,"EPG URL / файл",epg);Row(form,"M3U текст",paste);
  var help=new Label{Text="M3U: пълен адрес на списъка. Xtream: само http(s)://host:port. Портал: точен portal.php или server/load.php адрес и MAC от доставчика.\r\n\r\nПрофилите и адресите се пазят локално до EXE. Архивите съдържат същите данни за достъп.",AutoSize=true,MaximumSize=new Size(420,0),ForeColor=Color.Silver};Row(form,"",help);
  var buttons=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill};var save=new Button{Text="Запази",AutoSize=true};save.Click+=delegate{try{string kind=new[]{"m3u","file","text","xtream","portal"}[type.SelectedIndex];string a=address.Text.Trim();if(kind=="text"){if(Playlist.Parse(paste.Text,"").Count==0)throw new Exception("Постави M3U текст с канали.");a=Path.Combine(root,"playlist-"+Value.Id+".m3u");File.WriteAllText(a,paste.Text,new UTF8Encoding(true));kind="file";}else if(kind=="file"){if(!File.Exists(a))throw new Exception("M3U файлът не е намерен.");}else{Uri uri;if(!Uri.TryCreate(a,UriKind.Absolute,out uri)||!(uri.Scheme=="http"||uri.Scheme=="https"))throw new Exception("Въведи пълен HTTP(S) адрес.");if(kind=="xtream"&&!(uri.AbsolutePath=="/"||uri.AbsolutePath==""))throw new Exception("За Xtream въведи само сървъра и порта, без /get.php или /player_api.php.");}if(kind=="portal"&&!System.Text.RegularExpressions.Regex.IsMatch(mac.Text.Trim(),@"^([0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}$"))throw new Exception("MAC адресът трябва да е във формат 00:1A:79:XX:XX:XX.");Value.Name=name.Text.Trim()==""?"Моят доставчик":name.Text.Trim();Value.Type=kind;if(kind=="file"){Directory.CreateDirectory(Path.Combine(root,"playlists"));string rel="playlists/"+Value.Id+".m3u";string dest=Path.Combine(root,rel);if(!Path.GetFullPath(a).Equals(Path.GetFullPath(dest),StringComparison.OrdinalIgnoreCase))File.Copy(a,dest,true);a=rel;}Value.Address=a;Value.Username=user.Text.Trim();Value.Password=password.Text;Value.Mac=mac.Text.Trim();Value.Epg=epg.Text.Trim();Value.Category=new[]{"live","vod","series"}[category.SelectedIndex];DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(this,e.Message,"Профил");}};buttons.Controls.Add(save);var cancel=new Button{Text="Отказ",DialogResult=DialogResult.Cancel,AutoSize=true};buttons.Controls.Add(cancel);var del=new Button{Text="Изтрий профила",AutoSize=true};del.Click+=delegate{if(MessageBox.Show(this,"Да се премахне ли този профил?","Профил",MessageBoxButtons.YesNo)==DialogResult.Yes){Deleted=true;DialogResult=DialogResult.OK;}};buttons.Controls.Add(del);Row(form,"",buttons);CancelButton=cancel;
  type.SelectedIndexChanged+=delegate{UpdateFields();};UpdateFields();
 }
 void UpdateFields(){bool xt=type.SelectedIndex==3,pt=type.SelectedIndex==4;user.Enabled=xt;password.Enabled=xt;mac.Enabled=pt;category.Enabled=xt;paste.Enabled=type.SelectedIndex==2;address.Enabled=type.SelectedIndex!=2;}
 static TextBox T(string text){return new TextBox{Text=text??"",Dock=DockStyle.Fill,Margin=new Padding(3,5,3,5)};}
 public static void Row(TableLayoutPanel p,string label,Control c){int row=p.RowCount++;p.RowStyles.Add(new RowStyle(SizeType.AutoSize));p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(3,10,3,3)},0,row);p.Controls.Add(c,1,row);}
}
public class SettingsDialog : Form {
 NumericUpDown buffer;CheckBox hardware,auto;ComboBox aspect,theme;TextBox agent;
 public int Buffer{get{return (int)buffer.Value;}}public bool Hardware{get{return hardware.Checked;}}public bool AutoPlay{get{return auto.Checked;}}public string Aspect{get{return (string)aspect.SelectedItem;}}public string Theme{get{return new[]{"DARK","LIGHT","SYSTEM"}[theme.SelectedIndex];}}public string Agent{get{return agent.Text.Trim();}}
 public SettingsDialog(Settings s){Text="Настройки";Size=new Size(620,460);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);var form=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(20)};form.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,200));form.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(form);
  buffer=new NumericUpDown{Minimum=300,Maximum=75000,Increment=500,Value=s.BufferMs,Dock=DockStyle.Fill};hardware=new CheckBox{Text="Хардуерно декодиране",Checked=s.Hardware,AutoSize=true};auto=new CheckBox{Text="Последният канал при старт",Checked=s.AutoPlay,AutoSize=true};aspect=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};aspect.Items.AddRange(new object[]{"Оригинално","16:9","4:3"});aspect.SelectedItem=aspect.Items.Contains(s.Aspect)?s.Aspect:"Оригинално";theme=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};theme.Items.AddRange(new object[]{"Тъмна","Светла","Системна"});theme.SelectedIndex=s.Theme=="LIGHT"?1:s.Theme=="SYSTEM"?2:0;agent=new TextBox{Text=s.UserAgent,Dock=DockStyle.Fill};
  ProfileDialog.Row(form,"Буфер Windows (ms)",buffer);ProfileDialog.Row(form,"",new Label{Text="2500 ms = 2,5 s. По-голям буфер помага при нестабилна връзка, но увеличава забавянето.",AutoSize=true,MaximumSize=new Size(335,0)});ProfileDialog.Row(form,"Видео",hardware);ProfileDialog.Row(form,"Картина",aspect);ProfileDialog.Row(form,"Тема",theme);ProfileDialog.Row(form,"Старт",auto);ProfileDialog.Row(form,"HTTP User-Agent",agent);var b=new Button{Text="Запази",DialogResult=DialogResult.OK,AutoSize=true};ProfileDialog.Row(form,"",b);AcceptButton=b;
 }
